<?php require_once __DIR__.'/bootstrap.php'; require_login(); $cart=$_SESSION['cart']??[];if(!$cart){header('Location: cart.php');exit;}$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE active=1 AND id IN ($in)");$s->execute($ids);$items=[];$total=0;$cost=0;foreach($s as $p){$p['quantity']=(int)$cart[$p['id']];$total+=(float)$p['price']*$p['quantity'];$cost+=(float)$p['supplier_cost']*$p['quantity'];$items[]=$p;}if(!$items){header('Location: cart.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$fields=[];foreach(['name','phone','address1','address2','city','province','postal_code','country','country_code'] as $k)$fields[$k]=trim((string)($_POST[$k]??''));if($fields['name']===''||$fields['phone']===''||$fields['address1']===''||$fields['city']===''||$fields['province']===''||$fields['country']===''||!preg_match('/^[A-Za-z]{2}$/',$fields['country_code']))$error='Please complete all required shipping fields and use a two-letter country code.';else{try{$pdo->beginTransaction();$number='URW-'.strtoupper(bin2hex(random_bytes(6)));$s=$pdo->prepare("INSERT INTO orders(order_number,user_id,customer_name,email,phone,address1,address2,city,province,postal_code,country,country_code,subtotal,supplier_cost_total,profit_estimate,payment_status,fulfilment_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'pending','awaiting_payment')");$s->execute([$number,current_user()['id'],$fields['name'],current_user()['email'],$fields['phone'],$fields['address1'],$fields['address2'],$fields['city'],$fields['province'],$fields['postal_code'],$fields['country'],$fields['country_code'],$total,$cost,$total-$cost]);$oid=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO order_items(order_id,product_id,cj_vid,title,quantity,unit_price,supplier_cost,line_total) VALUES(?,?,?,?,?,?,?,?)');foreach($items as $p)$ins->execute([$oid,$p['id'],$p['cj_vid'],$p['title'],$p['quantity'],$p['price'],$p['supplier_cost'],$p['price']*$p['quantity']]);$pdo->commit();$_SESSION['cart']=[];header('Location: order-success.php?id='.$oid);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Checkout save failed: '.$e->getMessage());$error='Could not save the order. Please try again.';}}}page_start('Checkout'); ?><h1>Shipping details</h1><div class="panel" style="max-width:760px"><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif ?><p>Order total: <strong><?=money($total)?></strong></p><p class="muted">This starter checkout records an unpaid order. Payment confirmation must be integrated before any supplier order is placed.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row"><div><label>Recipient full name *</label><input name="name" required value="<?=e($_POST['name']??current_user()['name'])?>"></div><div><label>Phone *</label><input name="phone" required value="<?=e($_POST['phone']??'')?>"></div></div><label>Address line 1 *</label><input name="address1" required><label>Address line 2</label><input name="address2"><div class="row"><div><label>City *</label><input name="city" required></div><div><label>State / Province *</label><input name="province" required></div></div><div class="row"><div><label>Postal code</label><input name="postal_code"></div><div><label>Country *</label><input name="country" required></div><div><label>Country code (e.g. NG, US) *</label><input name="country_code" required minlength="2" maxlength="2" pattern="[A-Za-z]{2}"></div></div><button>Save order (payment not taken)</button></form></div><?php page_end();?>
